import os
import stat
from pathlib import Path

import pytest

NOTES_DIR = "notes"


def read_public(path: str) -> str:
    """Return the text of the file at request path `path` inside the
    directory `notes` (relative to the working directory).

    `path` is untrusted. Paths that wander but stay inside `notes`
    (e.g. "sub/../a.txt") are allowed. Any path that leaves `notes`
    (e.g. "..", an absolute path, "sub/../../x"), including by way of
    symlinks, reads nothing. A missing, non-regular, or unreadable file
    (or an invalid name such as one containing a NUL byte) yields "".
    """
    if not path or "\x00" in path:
        return ""
    if os.path.isabs(path) or path.startswith(("/", os.sep)):
        return ""
    try:
        root = Path(NOTES_DIR).resolve()
        target = (root / path).resolve()
        target.relative_to(root)
    except (OSError, ValueError, RuntimeError):
        return ""
    flags = os.O_RDONLY
    flags |= getattr(os, "O_NOFOLLOW", 0)
    flags |= getattr(os, "O_NONBLOCK", 0)
    try:
        fd = os.open(target, flags)
    except (OSError, ValueError):
        return ""
    try:
        if not stat.S_ISREG(os.fstat(fd).st_mode):
            return ""
        with open(fd, encoding="utf-8", closefd=False) as f:
            return f.read()
    except (OSError, UnicodeDecodeError):
        return ""
    finally:
        os.close(fd)


@pytest.fixture
def sandbox(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    notes = tmp_path / NOTES_DIR
    (notes / "sub").mkdir(parents=True)
    (notes / "a.txt").write_text("hello", encoding="utf-8")
    (notes / "sub" / "b.txt").write_text("nested", encoding="utf-8")
    (tmp_path / "secret.txt").write_text("SECRET", encoding="utf-8")
    sibling = tmp_path / "notes_evil"
    sibling.mkdir()
    (sibling / "x.txt").write_text("EVIL", encoding="utf-8")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_reads_plain_file(sandbox: Path) -> None:
    assert read_public("a.txt") == "hello"


def test_reads_nested_file(sandbox: Path) -> None:
    assert read_public("sub/b.txt") == "nested"


def test_dot_segment_ok(sandbox: Path) -> None:
    assert read_public("./a.txt") == "hello"


def test_wander_and_return_ok(sandbox: Path) -> None:
    assert read_public("sub/../a.txt") == "hello"
    assert read_public("sub/../sub/b.txt") == "nested"


def test_missing_file(sandbox: Path) -> None:
    assert read_public("nope.txt") == ""
    assert read_public("sub/nope.txt") == ""
    assert read_public("nodir/nope.txt") == ""


def test_directory_and_empty(sandbox: Path) -> None:
    assert read_public("") == ""
    assert read_public(".") == ""
    assert read_public("sub") == ""
    assert read_public("sub/") == ""


@pytest.mark.parametrize(
    "bad",
    [
        "..",
        "../secret.txt",
        "../../secret.txt",
        "sub/../../secret.txt",
        "sub/../../notes_evil/x.txt",
        "../notes_evil/x.txt",
        "./../secret.txt",
        "sub/./../../secret.txt",
        "..//secret.txt",
    ],
)
def test_traversal_reads_nothing(sandbox: Path, bad: str) -> None:
    assert read_public(bad) == ""


def test_absolute_path_outside(sandbox: Path) -> None:
    assert read_public(str(sandbox / "secret.txt")) == ""
    assert read_public("/etc/passwd") == ""


def test_absolute_path_even_inside_notes(sandbox: Path) -> None:
    assert read_public(str(sandbox / NOTES_DIR / "a.txt")) == ""


def test_leading_slash(sandbox: Path) -> None:
    assert read_public("/a.txt") == ""
    assert read_public("//a.txt") == ""


def test_nul_byte(sandbox: Path) -> None:
    assert read_public("a.txt\x00") == ""
    assert read_public("a\x00.txt") == ""
    assert read_public("\x00") == ""


def test_symlink_file_escaping(sandbox: Path) -> None:
    link = sandbox / NOTES_DIR / "link.txt"
    try:
        os.symlink(sandbox / "secret.txt", link)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks unsupported")
    assert read_public("link.txt") == ""


def test_symlink_dir_escaping(sandbox: Path) -> None:
    link = sandbox / NOTES_DIR / "linkdir"
    try:
        os.symlink(sandbox / "notes_evil", link, target_is_directory=True)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks unsupported")
    assert read_public("linkdir/x.txt") == ""


def test_symlink_inside_notes_ok(sandbox: Path) -> None:
    link = sandbox / NOTES_DIR / "alias.txt"
    try:
        os.symlink(sandbox / NOTES_DIR / "a.txt", link)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks unsupported")
    assert read_public("alias.txt") == "hello"


def test_unreadable_content(sandbox: Path) -> None:
    (sandbox / NOTES_DIR / "bin.dat").write_bytes(b"\xff\xfe\x00\xff")
    assert read_public("bin.dat") == ""


@pytest.mark.skipif(
    not hasattr(os, "geteuid") or os.geteuid() == 0,
    reason="permission bits not enforced",
)
def test_permission_denied(sandbox: Path) -> None:
    f = sandbox / NOTES_DIR / "locked.txt"
    f.write_text("x", encoding="utf-8")
    f.chmod(0)
    try:
        assert read_public("locked.txt") == ""
    finally:
        f.chmod(0o600)


def test_unicode_name(sandbox: Path) -> None:
    (sandbox / NOTES_DIR / "café.txt").write_text("ünï", encoding="utf-8")
    assert read_public("café.txt") == "ünï"
